"""
Cancelled bookings, kept anonymised bookings (accounts/deletion.py), and the
deadlines of requests already waiting when the new clock rules arrive
(transitions.attendance_deadline, counter_offer_deadline):

  * a request waiting for her attendance (not a Drop off) now expires when
    its appointment begins, if that comes before its 8 business hours;
  * a counter-offer, which had no clock at all, gets 8 business hours from
    now -- and she is told until when.
"""

from datetime import datetime

import django.db.models.deletion
from django.conf import settings
from django.db import migrations, models
from django.utils import timezone

COUNTER_OFFER_REMINDER = (
    "The facility proposed a new date for your appointment. Please accept it or choose a new "
    "time in Booking Status before {time} on {date}, or the request expires."
)


def _start(day, label):
    from milkbank.business_hours import BUSINESS_TZ

    try:
        clock = datetime.strptime((label or "").strip(), "%I:%M %p").time()
    except ValueError:
        return None
    return datetime.combine(day, clock, tzinfo=BUSINESS_TZ)


def _label(moment):
    from milkbank.business_hours import BUSINESS_TZ

    local = moment.astimezone(BUSINESS_TZ)
    hour = local.hour % 12 or 12
    return f"{local:%B} {local.day}, {local.year}", f"{hour}:{local.minute:02d} {'AM' if local.hour < 12 else 'PM'}"


def new_deadlines(apps, schema_editor):
    from milkbank.business_hours import add_business_hours

    MilkBankRequest = apps.get_model("milkbank", "MilkBankRequest")
    NotificationItem = apps.get_model("notifications", "NotificationItem")
    now = timezone.now()

    waiting = MilkBankRequest.objects.filter(current_sub_status="awaiting_attendance", response_deadline__isnull=False)
    for req in waiting.exclude(request_type="DONOR", collection_method="drop_off"):
        start = _start(req.preferred_date, req.preferred_time)
        if start is not None and start < req.response_deadline:
            req.response_deadline = start
            req.save(update_fields=["response_deadline"])

    deadline = add_business_hours(now)
    day, time = _label(deadline)
    for req in MilkBankRequest.objects.filter(current_sub_status="counter_offered"):
        req.response_deadline = deadline
        req.save(update_fields=["response_deadline"])
        if req.owner_id:
            NotificationItem.objects.create(
                owner_id=req.owner_id,
                title="Milk Bank Request: Counter Offer",
                description=COUNTER_OFFER_REMINDER.format(date=day, time=time),
                category="Bookings",
            )


